<?php
if(PHP_SAPI!=='cli')exit;
require __DIR__.'/../../new-project/app/src/bootstrap.php';
$catalog=json_decode(file_get_contents(ROOT.'/.local/shanghai-200/catalog.json'),true);$wanted=array_column($catalog['items'],'id');$label='上海地名仅作故事背景，不表示该地点存在真实灵异事件；人物、场所细节与情节为原创虚构。';$changes=[];
db()->beginTransaction();try{foreach(query('SELECT a.id,a.status,a.content,m.metadata FROM mvp_articles a JOIN mvp_article_meta m ON m.article_id=a.id WHERE a.site_id=9 FOR UPDATE')->fetchAll() as $a){$m=json_decode($a['metadata'],true);if(!in_array($m['catalog_id']??'',$wanted,true))continue;if($a['status']!=='draft')throw new RuntimeException('Only drafts may be cleaned');$offset=mb_strpos($a['content'],'## ');if($offset===false)continue;$pre=mb_substr($a['content'],0,$offset);if(mb_strlen($pre)>=300||!str_contains($pre,'虚构'))continue;$new=$label."\n\n".mb_substr($a['content'],$offset);if($new===$a['content'])continue;$m['presentation_cleanup']=['at'=>date(DATE_ATOM),'reason'=>'Consolidated repeated fiction preambles into one declaration; story text unchanged','model_review_retained'=>true];query('UPDATE mvp_articles SET content=?,updated_at=NOW() WHERE id=?',[$new,$a['id']]);query('UPDATE mvp_article_meta SET metadata=? WHERE article_id=?',[json_encode($m,JSON_UNESCAPED_UNICODE),$a['id']]);$changes[]=['id'=>$a['id'],'previous_preamble'=>$pre];}db()->commit();}catch(Throwable $e){db()->rollBack();throw $e;}
file_put_contents(ROOT.'/.local/shanghai-200/label-cleanup.json',json_encode($changes,JSON_UNESCAPED_UNICODE|JSON_PRETTY_PRINT));echo 'Consolidated labels: '.count($changes).PHP_EOL;
